{
    "$defs": {
        "FAQ": {
            "properties": {
                "question": {
                    "description": "The question part of the FAQ",
                    "title": "Question",
                    "type": "string"
                },
                "answer": {
                    "description": "The answer to the FAQ question",
                    "title": "Answer",
                    "type": "string"
                }
            },
            "required": [
                "question",
                "answer"
            ],
            "title": "FAQ",
            "type": "object"
        }
    },
    "properties": {
        "faqs": {
            "description": "List of FAQs generated for a webpage or company section",
            "items": {
                "$ref": "#/$defs/FAQ"
            },
            "title": "Faqs",
            "type": "array"
        }
    },
    "required": [
        "faqs"
    ],
    "title": "FAQList",
    "type": "object"
}
